window.TEST_PARTS=window.TEST_PARTS||{};window.TEST_PARTS["test7"]=(window.TEST_PARTS["test7"]||[]).concat([{"n":1,"q":"Կայանումն արգելվում է","options":["Կամուրջների, էստակադների եւ ուղեկամուրջների վրա։","Կամուրջների, էստակադների եւ ուղեկամուրջների տակ։","Թվարկած բոլոր դեպքերում։"],"ans":3,"page":1},{"n":2,"q":"Թույլատրվու՞մ է արդյոք ուղեւոր իջեցնել ճանապարհի այն տեղում, որտեղ եզրաքարի վերին մակերեսին գծված է դեղին հոծ գիծ եւ տեղադրված է «Կանգառն արգելվում է» նշանը։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է ընդհանուր օգտագործման տրանսպորտային միջոցների բացակայության դեպքում","Թույլատրվում է միայն ընդհանուր օգտագործման տրանսպորտային միջոցներին"],"ans":2,"page":1,"images_inline":["data:image/jpeg;base64,"]},{"n":3,"q":"Ազդու՞մ է արդյոք արգելող նշանը ճանապարհի այն հատվածի վրա, որտեղ կանգառ է կատարել վարորդը։","options":["Ազդում է","Չի ազդում"],"ans":1,"page":2,"images_inline":["data:image/jpeg;base64,"]},{"n":4,"q":"Երկաթուղային գծանցներից ի՞նչ հեռավորության վրա է արգելվում տրանսպորտային միջոցների կայանումը։","options":["300 մ","150 մ","100 մ","50 մ","25 մ"],"ans":5,"page":2},{"n":5,"q":"Թույլատրվու՞մ է արդյոք տվյալ դեպքում կանգ առնել՝ ուղեւոր իջեցնելու համար։","options":["Թույլատրվում է, եթե դա չի խոչընդոտի ընդհանուր օգտագործման տրանսպորտային միջոցների երթեւեկությանը","Արգելվում է"],"ans":1,"page":2,"images_inline":["data:image/jpeg;base64,"]},{"n":6,"q":"Վարորդներից ո՞րն է պարտավոր կանգ առնել։","options":["Թեթեւ մարդատար ավտոմոբիլի վարորդը","Ավտոբուսի վարորդը","Երկու վարորդներն էլ"],"ans":1,"page":3,"images_inline":["data:image/jpeg;base64,"]},{"n":7,"q":"Տվյալ ճանապարհային գծանշումը թույլատրում է երթեւեկել","options":["Միայն դեպի ձախ։","Դեպի ձախ եւ հակառակ ուղղությամբ։","Միայն հակառակ ուղղությամբ։","Ուղիղ, ձախ եւ հակառակ ուղղությամբ։"],"ans":2,"page":3,"images_inline":["data:image/jpeg;base64,"]},{"n":8,"q":"Ո՞ր տրանսպորտային միջոցներին է թույլատրվում կայանել տվյալ ճանապարհային նշանի ազդեցության գոտում։","options":["Միայն ընդհանուր օգտագործման տրանսպորտային միջոցներին","Այն տրանսպորտային միջոցներին, որոնք վարում են հաշմանդամները, եւ միացված հաշվիչով տաքսիներին"],"ans":2,"page":4,"images_inline":["data:image/jpeg;base64,"]},{"n":9,"q":"Ի՞նչ է նշանակում տվյալ ճանապարհային գծանշումը։","options":["Ուղեւորներ նստեցնելու-իջեցնելու տեղ","Ընդհանուր օգտագործման տրանսպորտային միջոցների կանգառի կետ","Ընդհանուր օգտագործման տրանսպորտային միջոցների կանգառի եւ տաքսիների կայանման տեղ"],"ans":2,"page":4,"images_inline":["data:image/jpeg;base64,"]},{"n":10,"q":"Ի՞նչ է ցույց տալիս հորիզոնական գծանշման դեղին հոծ գիծը։","options":["Այն տեղը, որտեղ արգելվում է տրանսպորտային միջոցների կանգառը եւ կայանումը","Այն տեղը, որտեղ թույլատրվում է կանգառ կատարել՝ ուղեւորներ իջեցնելու կամ տրանսպորտային միջոցը բեռնաթափելու համար","Այն տեղը, որտեղ արգելվում է տրանսպորտային միջոցների կայանումը"],"ans":1,"page":5,"images_inline":["data:image/jpeg;base64,"]},{"n":11,"q":"Թույլատրվու՞մ է արդյոք վարորդին հատել տրանսպորտային միջոցների կայանման տեղերի սահմանները նշող գծանշման հոծ գիծը։","options":["Արգելվում է","Թույլատրվում է։"],"ans":2,"page":5,"images_inline":["data:image/jpeg;base64,"]},{"n":12,"q":"Սլաքներով նշված ո՞ր ուղղություններով է թույլատրվում երթեւեկությունը։","options":["Միայն ուղիղ","Դեպի ձախ եւ հակառակ ուղղությամբ","Ուղիղ, դեպի ձախ եւ հակառակ ուղղությամբ"],"ans":1,"page":6,"images_inline":["data:image/jpeg;base64,"]},{"n":13,"q":"Ի՞նչ է ցույց տալիս այս գծանշումը։","options":["Հետիոտնային անցում, որտեղ երթեւեկությունը կարգավորվում է լուսացույցով","Այն տեղը, որտեղ հեծանվային արահետը հատում է ճանապարհի երթեւեկելի մասը","Այն տեղը, որտեղ հետիոտնային արահետը հատում է ճանապարհի երթեւեկելի մասը"],"ans":2,"page":6,"images_inline":["data:image/jpeg;base64,"]},{"n":14,"q":"Քանի՞ գոտի ունի ճանապարհը, որտեղ հանդիպակաց ուղղությունների տրանսպորտային հոսքերը բաժանվում են կրկնակի հոծ գծերով։","options":["Երկու գոտի","Երկու կամ երեք գոտի","Երեք գոտի","Չորս եւ ավելի գոտիներ"],"ans":4,"page":7,"images_inline":["data:image/jpeg;base64,"]},{"n":15,"q":"Ի՞նչ են նախազգուշացնում երթեւեկելի մասի վրա գծանշված սլաքները։","options":["Նախազգուշացնում են վարորդին ճանապարհի վտանգավոր հատվածին մոտենալու մասին","Նախազգուշացնում են երթեւեկության գոտու վերջին մոտենալու մասին","Ցույց են տալիս ճանապարհի վտանգավոր շրջադարձի ուղղությունը"],"ans":2,"page":7,"images_inline":["data:image/jpeg;base64,"]},{"n":16,"q":"Գծանշման այս գծերից ո՞րն է օգտագործվում դարձափոխային երթեւեկությամբ գոտիները նշելու համար։","options":["1-ին գիծը","2-րդ գիծը","3-րդ գիծը","2-րդ եւ 3 -րդ գծերը","3-րդ եւ 4 -րդ գծերը"],"ans":2,"page":8,"images_inline":["data:image/jpeg;base64,"]},{"n":17,"q":"Որտե՞ղ է գծվում կանգառը եւ կայանումն արգելող տեղերը նշող դեղին հոծ գիծը։","options":["Երթեւեկելի մասի վրա","Երթեւեկելի մասի եզրի մոտ","Երթեւեկելի մասի եզրի մոտ կամ եզրաքարի վերին մակերեսին","Միայն եզրաքարի վերին մակերեսին"],"ans":3,"page":8,"images_inline":["data:image/jpeg;base64,"]},{"n":18,"q":"Ճանապարհային նշաններից որի՞ հետ կարող է կիրառվել դեղին գույնի ընդհատվող գծանշումը։","options":["«Կանգառն արգելվում է»","«Կայանելն արգելվում է»","«Կայանելն արգելվում է ամսվա կենտ օրերին»"],"ans":2,"page":9,"images_inline":["data:image/jpeg;base64,"]},{"n":19,"q":"Ո՞ր տրանսպորտային միջոցներին է թույլատրվում երթեւեկել երթեւեկելի մասի աջ գոտիով։","options":["Բոլոր մեխանիկական տրանսպորտային միջոցներին","Ընդհանուր օգտագործման տրանսպորտային միջոցներին եւ տաքսիներին","Միայն հեծանիվներին","Միայն ընդհանուր օգտագործման տրանսպորտային միջոցներին"],"ans":4,"page":9,"images_inline":["data:image/jpeg;base64,"]},{"n":20,"q":"Այս ճանապարհային գծանշումն ունի հետեւյալ նշանակությունը։","options":["Ցույց է տալիս մայթամերձ կայանման տեղերը, որտեղ նշված են մեխանիկական տրանսպորտային միջոցների կանգնեցման ձեւերը","Ցույց է տալիս այն տեղերը, որտեղ արգելվում է մեխանիկական տրանսպորտային միջոցների կանգառը","Ցույց է տալիս ընդհանուր օգտագործման տրանսպորտային միջոցների կանգառի կետերը եւ տաքսիների կայանման վայրերը"],"ans":3,"page":10,"images_inline":["data:image/jpeg;base64,"]},{"n":21,"q":"Այս հորիզոնական ճանապարհային գծանշումը ցույց է տալիս","options":["Երթեւեկելի մասի նեղացումը, որտեղ նվազում է երթեւեկության գոտիների քանակը տվյալ ուղղությամբ։","Այն տեղը, որտեղ վարորդը պետք է անհրաժեշտության դեպքում կանգ առնի` հատվող ճանապարհով երթեւեկող տրանսպորտային միջոցներին ճանապարհը զիջելու համար։","Մոտեցում դեպի կանգառն արգելված տեղին։"],"ans":2,"page":10,"images_inline":["data:image/jpeg;base64,"]},{"n":22,"q":"Թույլատրվու՞մ է արդյոք մուտք գործել սպիտակ լայն գծերով նշված ուղղորդ կղզյակ։","options":["Թույլատրվում է միայն կանգառ կատարելու համար","Թույլատրվում է հետընթացի ժամանակ","Արգելվում է"],"ans":3,"page":11,"images_inline":["data:image/jpeg;base64,"]},{"n":23,"q":"Ինչպե՞ս պետք է վարվի վարորդը՝ մոտենալով խաչմերուկին՝ «Կանգ - գիծ» գծանշման եւ լուսացույցի կանաչ ազդանշանի պայմաններում։","options":["Կանգ առնի «Կանգ-գծի» մոտ, որից հետո վերսկսի երթեւեկությունը","Շարունակի երթեւեկությունը խաչմերուկով` առանց կանգառի"],"ans":2,"page":11},{"n":24,"q":"Ի՞նչ է ցույց տալիս այս գծանշումը։","options":["Հետիոտնային անցում","Այն տեղը, որտեղ հեծանվային արահետը հատում է ճանապարհի երթեւեկելի մասը","Անասուններ քշելու համար նախատեսված տեղ"],"ans":2,"page":11,"images_inline":["data:image/jpeg;base64,"]},{"n":25,"q":"Վարորդը որտե՞ղ պետք է կանգնեցնի տրանսպորտային միջոցն այս գծանշման առկայության դեպքում։","options":["Գծանշման մոտ","Գծանշման վրա","Գծանշումից ոչ պակաս, քան 5մ հեռավորության վրա"],"ans":1,"page":12,"images_inline":["data:image/jpeg;base64,"]},{"n":26,"q":"Ի՞նչ է նշանակում այս գծանշումը։","options":["Ընդհանուր օգտագործման տրանսպորտային միջոցների համար նախատեսված երթեւեկության գոտի","Հատուկ նշանակության ավտոմոբիլների համար նախատեսված երթեւեկության գոտի","Ցույց է տալիս երթեւեկության այն գոտիների սահմանները, որտեղ իրականացվում է դարձափոխային կարգավորում"],"ans":3,"page":12,"images_inline":["data:image/jpeg;base64,"]},{"n":27,"q":"Թույլատրվու՞մ է արդյոք նշված վայրում հետադարձ կատարել։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"page":13,"images_inline":["data:image/jpeg;base64,"]},{"n":28,"q":"Թույլատրվու՞մ է արդյոք տվյալ գծանշման առկայության դեպքում զբոսաշրջության երթուղով ընթացող ավտոբուսի վարորդին մուտք գործել «A» գծանշումով գոտի։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"page":13,"images_inline":["data:image/jpeg;base64,"]},{"n":29,"q":"Ի՞նչ է ցույց տալիս ընդհատվող լայն գծի տեսքով գծանշումը։","options":["Երթեւեկելի մասի եւ կողնակի միջեւ առկա սահմանը","Երթեւեկելի մասի հիմնական գոտու եւ թափառքի գոտու միջեւ առկա սահմանը","Երթեւեկելի մասի հիմնական գոտու եւ արգելակման գոտու միջեւ առկա սահմանը"],"ans":2,"page":14,"images_inline":["data:image/jpeg;base64,"]},{"n":30,"q":"Ո՞ր ավտոմոբիլին է թույլատրվում կանգառ կատարել այս նշանների ազդման գոտում։","options":["Կարմիրին","Երկու ավտոմոբիլներին էլ","Ոչ մեկին","Դեղինին՝ «Հաշմանդամ» ճանաչման նշանով կահավորված"],"ans":4,"page":14,"images_inline":["data:image/jpeg;base64,"]},{"n":31,"q":"Ո՞ր նկարում է վարորդը ճիշտ կատարել կանգառ` ուղեւորներ իջեցնելու համար։","options":["Ձախ նկարում","Երկու նկարներում էլ","Աջ նկարում"],"ans":1,"page":15,"images_inline":["data:image/jpeg;base64,"]},{"n":32,"q":"Որպես գնացքի կանգառի ազդանշան ծառայում է","options":["Ձեռքի շրջանաձեւ շարժումը (ցերեկը` վառ գույնի լաթով կամ որեւէ լավ տեսանելի առարկայով, գիշերը` ջահով կամ լապտերով)։","Սկավառակով կամ կարմիր դրոշակով գլխավերեւ բարձրացված ձեռքը։","Առաջ պարզած ձեռքը։","Վեր եւ վար ճոճվող` առաջ պարզած ձեռքը։"],"ans":1,"page":15},{"n":33,"q":"Բնակավայրերում, յուրաքանչյուր ուղղությամբ մեկ երթեւեկելի գոտի ունեցող եւ մեջտեղում տրամվայի գծեր չունեցող ճանապարհների ձախ կողմում կանգառն ու կայանումը","options":["Թույլատրվում է։","Արգելվում է։"],"ans":1,"page":15},{"n":34,"q":"«Կանգ-գծից» կամ «Երթեւեկությունն առանց կանգառի արգելվում է» նշանից ի՞նչ հեռավարության վրա պետք է կանգնեցվի տրանսպորտային միջոցը՝ մոտեցող գնացքին ճանապարհը զիջելու համար։","options":["1,5 մ","2,5 մ","5 մ","10 մ","Անմիջապես «Կանգ-գծի» եւ (կամ) նշանի մոտ"],"ans":5,"page":15},{"n":35,"q":"Թույլատրվու՞մ է արդյոք կանգառը նշված տեղում։","options":["Թույլատրվում է","Արգելվում է"],"ans":2,"page":16,"images_inline":["data:image/jpeg;base64,"]},{"n":36,"q":"Թույլատրվու՞մ է արդյոք ավտոմոբիլի կանգառն այս վայրում։","options":["Արգելվում է, քանի որ գծանշման ընդհատվող գծի եւ կանգ առած տրանսպորտային միջոցի միջեւ հեռավորությունը պակաս է 3 մետրից","Արգելվում է ամսվա զույգ օրերին","Թույլատրվում է"],"ans":3,"page":16,"images_inline":["data:image/jpeg;base64,"]},{"n":37,"q":"Ո՞ր տրանսպորտային միջոցի վարորդն է խախտել կայանման կանոնները։","options":["Կապույտ ավտոմոբիլի վարորդը","Կարմիր ավտոմոբիլի վարորդը","Երկու վարորդներն էլ խախտել են","Երկու վարորդներն էլ չեն խախտել"],"ans":3,"page":17,"images_inline":["data:image/jpeg;base64,"]},{"n":38,"q":"Բնակավայրերից դուրս որտե՞ղ է թույլատրվում երկարատեւ հանգստի, գիշերակացի եւ այլ նպատակներով կայանելը։","options":["Ճանապարհի կողնակներին","Կայանման համար նախատեսված հրապարակներում կամ ճանապարհի սահմաններից դուրս","Ճանապարհի երթեւեկելի մասի աջ կողմում` չխոչընդոտելով այլ տրանսպորտային միջոցների երթեւեկությունը","Ճանապարհի ձախ կողմում` ապահովելով ճանապարհային երթեւեկության անվտանգությունը"],"ans":2,"page":17},{"n":39,"q":"Կանգառն արգելվում է, եթե հոծ գծի եւ կանգնած տրանսպորտային միջոցի միջեւ տարածությունը կազմում է","options":["6 մ։","","5 մ։","4 մ։","","5 մ։","","5 մ։"],"ans":5,"page":17,"images_inline":["data:image/jpeg;base64,"]},{"n":40,"q":"Եթե երկաթուղային գծանցով երթեւեկությունը արգելված է, եւ բացակայում են լուսացույցը, ճանապարհային նշանները, գծանշումն ու ուղեփակոցը, ապա վարորդը պետք է կանգնի","options":["Մոտակա ռելսից ոչ պակաս, քան 5 մ հեռավորության վրա։","Մոտակա ռելսից ոչ պակաս, քան 7 մ հեռավորության վրա։","Մոտակա ռելսից ոչ պակաս, քան 10 մ հեռավորության վրա։"],"ans":3,"page":18},{"n":41,"q":"Ի՞նչ հեռավորության վրա է արգելվում տրանսպորտային միջոցների կայանումը երկաթուղային գծանցներից։","options":["15 մ","50 մ","100 մ","150 մ"],"ans":1,"page":18},{"n":42,"q":"Ո՞ր պատասխանում են ճիշտ թվարկած կանգառի կանոնները խախտած վարորդները։","options":["Կարմիր ավտոմոբիլի եւ մոտոցիկլի վարորդները","Կապույտ ավտոմոբիլի վարորդը","Մոտոցիկլի վարորդը","Բոլոր տրանսպորտային միջոցների վարորդները"],"ans":4,"page":18,"images_inline":["data:image/jpeg;base64,"]},{"n":43,"q":"Ո՞ր տրանսպորտային միջոցների վարորդներն են սխալ կանգառ կատարել ուղեւորներ իջեցնելու համար։","options":["Թեթեւ մարդատար ավտոմոբիլի վարորդը","Մոտոցիկլի վարորդը","Ավտոբուսի վարորդը","Մոտոցիկլի և ավտոբուսի վարորդները","Բոլոր վարորդները"],"ans":4,"page":19,"images_inline":["data:image/jpeg;base64,"]},{"n":44,"q":"Եթե երկաթուղային գծանցով երթեւեկությունն արգելված է, եւ բացակայում են լուսացույցը, ճանապարհային նշաններն ու գծանշումը, ապա վարորդը պետք է կանգնի","options":["Ուղեփակոցից ոչ պակաս, քան 5 մ հեռավորության վրա։","Ուղեփակոցից ոչ պակաս, քան 3 մ հեռավորության վրա։","Ուղեփակոցից անմիջապես առաջ։"],"ans":1,"page":19},{"n":45,"q":"Թույլատրվու՞մ է զբոսաշրջային ավտոբուսին երթևեկել «A» գծանշմամբ գոտիով։","options":["Արգելվում է։","Թույլատրվում է։"],"ans":1,"page":19,"images_inline":["data:image/jpeg;base64,"]},{"n":46,"q":"Ի՞նչ է նշանակում երթեւեկելի մասի գոտում գծանշված «A» տառը։","options":["Ճանապարհի (երթուղու) համարը","Ընդհանուր օգտագործման տրանսպորտային միջոցների երթեւեկության համար նախատեսված հատուկ գոտի",",,A\" կարգի տրանսպորտային միջոցների երթեւեկության համար նախատեսված հատուկ գոտի"],"ans":2,"page":20,"images_inline":["data:image/jpeg;base64,"]},{"n":47,"q":"Տրանսպորտային միջոցին թույլատրվու՞մ է կանգնել նշված տեղում ուղեւորներ իջեցնելու համար։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է` բայց մայթին բարձրանալով"],"ans":2,"page":20,"images_inline":["data:image/jpeg;base64,"]},{"n":48,"q":"Թույլատրվու՞մ է շարունակել երթեւեկությունը սլաքով նշված ուղղությամբ։","options":["Արգելվում է","Թույլատրվում է բոլոր դեպքերում","Թույլատրվում է՝ ուղեւորներ իջեցնելու նպատակով կանգառ կատարելու համար","Թույլատրվում է՝ բեռնատար ավտոմոբիլին վազանցելու նպատակով"],"ans":3,"page":21,"images_inline":["data:image/jpeg;base64,"]},{"n":49,"q":"Այսպիսի ուղղաձիգ գծանշմամբ նշվում են","options":["Կամրջի, թունելի ստորին եզրերը։","Չլուսավորված թունելների մուտքը։","Ճանապարհային շինությունների ցանկացած տարր, որը վտանգ է ստեղծում երթեւեկության համար։"],"ans":1,"page":21,"images_inline":["data:image/jpeg;base64,"]},{"n":50,"q":"Ավտոբուսի վարորդը կատարել է կանգառ ուղեւորներ նստեցնելու նպատակով։ Թեթեւ մարդատար ավտոմոբիլը երթեւեկում է 70կմ/ժ արագությամբ։ Ո՞ր տրանսպորտային միջոցի վարորդն է խախտում ճանապարհային երթեւեկության կանոնների պահանջները։","options":["Ոչ ոք","Ավտոբուսի վարորդը","Թեթեւ մարդատար ավտոմոբիլի վարորդը","Երկու վարորդներն էլ"],"ans":1,"page":22,"images_inline":["data:image/jpeg;base64,"]},{"n":51,"q":"Թվարկվածներից ո՞ր դեպքում կարող է ավտոբուսի վարորդն անցնել երկկողմ երթևեկության եռագոտի ճանապարհի մեջտեղի գոտի, որն օգտագործվում է երկու ուղղությամբ երթևեկության համար։","options":["Վազանցելու կամ շրջանցելու նպատակով։","Ձախ շրջադարձ կամ հետադարձ կատարելու նպատակով։","Վերոնշյալ երկու դեպքում էլ։","Ոչ մի պատասխանը ճիշտ չէ։"],"ans":3,"page":22,"images_inline":["data:image/jpeg;base64,"]},{"n":52,"q":"Որտե՞ղ պետք է կանգ առնի վարորդը տվյալ իրավիճակում։","options":["Կանգառը պարտադիր չէ","Լուսացույցի առջեւ","«Կանգ-գիծ» գծանշման առջեւ","Երթեւեկելի գոտիների հատման առջեւ"],"ans":3,"page":23,"images_inline":["data:image/jpeg;base64,"]},{"n":53,"q":"Թույլատրվու՞մ է կանոնավոր ուղևորափոխադրումներ իրականացնող ավտոբուսի վարորդին ուղևորներ նստեցնելու նպատակով կանգառ կատարել նշված վայրում։","options":["Արգելվում է։","Թույլատրվում է։"],"ans":1,"page":23,"images_inline":["data:image/jpeg;base64,"]},{"n":54,"q":"Զբոսաշրջային ավտոբուսի վարորդը երկարատև հանգստի նպատակով իրավունք ունի՞ կանգ առնել նշված վայրում։","options":["Իրավունք չունի։","Իրավունք ունի։"],"ans":1,"page":24,"images_inline":["data:image/jpeg;base64,"]},{"n":55,"q":"Դեպի ձախ երթեւեկությունը շարունակելու համար որտե՞ղ պետք է կանգ առնի ավտոբուսի վարորդը ճանապարհը թեթեւ մարդատար ավտոմոբիլին զիջելու համար։","options":["Ճանապարհային նշանի առջեւ","Գծանշման մոտ","Վարորդի հայեցողությամբ անվտանգ տեղում"],"ans":2,"page":24,"images_inline":["data:image/jpeg;base64,"]},{"n":56,"q":"Տվյալ իրավիճակում որտե՞ղ պետք է կանգ առնել։","options":["Առաջին ճանապարհային նշանի մոտ","«Կանգ-գիծ» գծանշման առջեւ","Երկրորդ ճանապարհային նշանի մոտ","Կանգառը պարտադիր չէ"],"ans":2,"page":25,"images_inline":["data:image/jpeg;base64,"]},{"n":57,"q":"Տվյալ նշանի ազդեցության գոտում ո՞ր տրանսպորտային միջոցներին է թույլատրվում կանգառ կատարել։","options":["Միայն ընդհանուր օգտագործման տրանսպորտային միջոցներին","Միայն հաշմանդամների կողմից ղեկավարվող տրանսպորտային միջոցներին","Միայն միացված հաշվիչով տաքսիներին","Բոլորին արգելվում է"],"ans":4,"page":25,"images_inline":["data:image/jpeg;base64,"]},{"n":58,"q":"Տվյալ ճանապարհային նշանների ազդման գոտում թույլատրվու՞մ է կանգառ կատարել՝ ուղեւորներ նստեցնելու նպատակով։","options":["Թույլատրվում է","Արգելվում է"],"ans":1,"page":26,"images_inline":["data:image/jpeg;base64,"]},{"n":59,"q":"Ո՞ր տրանսպորտային միջոցների համար է առանձնացված «A» տառով գծանշված գոտին։","options":["Միայն ավտոբուսների համար, որոնք շարժվում են սահմանված երթուղով","Տրոլեյբուսների եւ տաքսիների համար","Ընդհանուր օգտագործման տրանսպորտային միջոցների համար"],"ans":3,"page":26,"images_inline":["data:image/jpeg;base64,"]},{"n":60,"q":"Թույլատրվու՞մ է ավտոբուսների կանգառն ու կայանումը բնակավայրերում երթևեկելի մասի ձախ կողմում` միակողմ երթևեկության ճանապարհներին։","options":["Թույլատրվում է։","Արգելվում է։","Թույլատրվում է միայն կանգառ կատարելու համար։"],"ans":1,"page":26},{"n":61,"q":"Կանգառի կետերի տարածքից դուրս թույլատրվու՞մ է ընդհանուր օգտագործման տրանսպորտային միջոցներին կանգառ կատարել։","options":["Արգելվում է։","Թույլատրվում է։"],"ans":1,"page":26},{"n":62,"q":"Թույլատրվու՞մ է ավտոբուսների կայանումը բնակելի գոտիներում եւ բակային տարածքներում։","options":["Արգելվում է։","Թույլատրվում է` դրա համար նախատեսված տեղերում։","Թույլատրվում է։"],"ans":2,"page":27},{"n":63,"q":"Թո՞ւյլատրվում է կանգառը նշված վայրում։","options":["Այո","Ոչ"],"ans":1,"page":27,"images_inline":["data:image/jpeg;base64,"]},{"n":64,"q":"Թույլատրվո՞ւմ է կայանումն այս իրավիճակում։","options":["Այո","Միայն օրվա լուսավոր ժամերին","Ոչ"],"ans":3,"page":27,"images_inline":["data:image/jpeg;base64,"]},{"n":65,"q":"Ո՞ր վայրում է թույլատրվում կանգառ կատարել։","options":["Միայն B","Միայն A և B","Միայն A և C","Ոչ մի վայրում"],"ans":2,"page":28,"images_inline":["data:image/jpeg;base64,"]},{"n":66,"q":"Թույլատրվու՞մ է կանգառ կատարել նշված վայրում։","options":["Այո","Արգելվում է","Միայն ուղևոր նստեցնելու նպատակով"],"ans":2,"page":28,"images_inline":["data:image/jpeg;base64,"]},{"n":67,"q":"Նշված իրավիճակում ուղևոր նստեցնելու նպատակով կանգառ թույլատրվու՞մ է։","options":["Այո","Ոչ"],"ans":2,"page":28,"images_inline":["data:image/jpeg;base64,"]},{"n":68,"q":"Նշվածներից ո՞ր դեպքում է թույլատրվում կանգառ կատարել։","options":["Միայն B","Միայն C","A և C","Բոլոր դեպքերում"],"ans":1,"page":29,"images_inline":["data:image/jpeg;base64,"]},{"n":69,"q":"Կանգառն արգելվում է","options":["Երկաթուղային գծանցում։","Երկաթուղային գծանցում և 50մ գծանցին մոտ։","Երկաթուղային գծանցում և 50մ գծանցից առաջ։"],"ans":1,"page":29},{"n":70,"q":"Կայանումն արգելվում է","options":["Երկաթուղային գծանցում։","Երկաթուղային գծանցում և 50մ գծանցին մոտ։","Երկաթուղային գծանցում և 50մ գծանցից առաջ։"],"ans":2,"page":29},{"n":71,"q":"Ո՞ր տարբերակում է նշված ճիշտ կանգառ կատարողը։","options":["Միայն C","Միայն A և C","Միայն B և C","Երեք դեպքերում էլ"],"ans":1,"page":29,"images_inline":["data:image/jpeg;base64,"]},{"n":72,"q":"Պարտավո՞ր եք արդյոք զիջել բեռնատարին։","options":["Այո","Ոչ"],"ans":2,"page":30,"images_inline":["data:image/jpeg;base64,"]},{"n":73,"q":"Ե՞րբ է թույլատրվում հատել գծանշումը։","options":["Հետիոտնային անցումից առաջ","Հետիոտնային անցումից հետո"],"ans":2,"page":30,"images_inline":["data:image/jpeg;base64,"]},{"n":74,"q":"Նշված իրավիճակում թույլատրվու՞մ է արդյոք կանգառ կատարել ուղևոր նստեցնելու նպատակով։","options":["Այո","Թույլատրվում է միայն ընդհանուր օգտագործման տրանսպորտային միջոցի վարորդին","Ոչ"],"ans":2,"page":30,"images_inline":["data:image/jpeg;base64,"]}]);